"""The stationary order-two/order-four line writer described in P-R-009."""

from collections import Counter, defaultdict, deque
import random

from vs import dsl


SPACE = " "
END = "$"
ORDER_SHORT = 2
ORDER_LONG = 4
WORD_MEMORY = 300


def start_for(opener):
    return ("^P" if opener else "^L",) * ORDER_LONG


def layout_lines(pages):
    for page_index, page in enumerate(pages):
        first_line = True
        for line in page.lines:
            if not line.words:
                continue
            paragraph = line.unit == "P"
            opener = paragraph and (line.para_start or first_line)
            yield page_index, page.section, line, opener
            if paragraph:
                first_line = line.para_end


def learn(pages):
    contexts = {order: defaultdict(Counter) for order in (0, 1, ORDER_SHORT, ORDER_LONG)}
    for _, _, line, opener in layout_lines(pages):
        if line.unit != "P" or any("?" in word or "*" in word for word in line.words):
            continue
        symbols = []
        for word in line.words:
            symbols.extend(dsl.SEG(word))
            symbols.append(SPACE)
        symbols[-1] = END
        history = list(start_for(opener))
        for glyph in symbols:
            for order, table in contexts.items():
                context = tuple(history[-order:]) if order else ()
                table[context][glyph] += 1
            history.append(glyph)
    return contexts


class Writer:
    def __init__(self, contexts, seed, forbidden):
        self.contexts = contexts
        self.random = random.Random(seed)
        self.forbidden = forbidden
        self.memory = deque()
        self.counts = Counter()

    def draw(self, weights):
        return self.random.choices(list(weights), weights=list(weights.values()))[0]

    def distribution(self, history, order):
        for size in (order, ORDER_SHORT, 1):
            options = self.contexts[size].get(tuple(history[-size:]))
            if options:
                return options
        return self.contexts[0][()]

    def glyph(self, history):
        order = ORDER_SHORT if self.random.random() < 0.60 else ORDER_LONG
        return self.draw(self.distribution(history, order))

    def remember(self, word):
        self.memory.append(word)
        self.counts[word] += 1
        if len(self.memory) > WORD_MEMORY:
            expired = self.memory.popleft()
            self.counts[expired] -= 1
            if not self.counts[expired]:
                del self.counts[expired]

    def whole_copy(self, history):
        candidates = {word: n for word, n in self.counts.items() if n >= 2}
        if not candidates:
            return ()
        options = self.distribution(history, ORDER_SHORT)
        preferred = {word: n for word, n in candidates.items() if word[0] in options}
        return self.draw(preferred or candidates)

    def line(self, opener):
        while True:
            previous = tuple(self.memory)
            history = list(start_for(opener))
            words = []
            current = []
            while len(history) < 504:
                if words and not current and not opener and self.random.random() < 0.25:
                    copied = self.whole_copy(history)
                    if copied:
                        current = list(copied)
                        history.extend(copied)
                        boundaries = {
                            key: weight for key, weight in self.distribution(history, ORDER_SHORT).items()
                            if key in (SPACE, END)
                        }
                        glyph = self.draw(boundaries or {SPACE: 1, END: 1})
                    else:
                        glyph = self.glyph(history)
                else:
                    glyph = self.glyph(history)
                if glyph in (SPACE, END):
                    if current:
                        words.append("".join(current))
                        self.remember(tuple(current))
                        current = []
                    elif glyph == SPACE:
                        continue
                    if glyph == END and words:
                        break
                    if not words:
                        continue
                else:
                    current.append(glyph)
                history.append(glyph)
            if current:
                words.append("".join(current))
                self.remember(tuple(current))
            if words and not any(tuple(words[i:i + 4]) in self.forbidden for i in range(len(words) - 3)):
                return words
            self.memory = deque(previous)
            self.counts = Counter(previous)

