"""Calibrate the section-word statistic on stationary, planted and placebo texts."""

from collections import Counter, defaultdict
from concurrent.futures import ProcessPoolExecutor
from dataclasses import dataclass
import json
import math
from pathlib import Path
import random
import string
import sys

import numpy as np
from vs import corpus, dsl, redteam

from stationary import Writer, layout_lines, learn


WORK = Path(__file__).resolve().parent
PLAN = json.loads((WORK / "plan.json").read_text())
SELECT = {"unit": ["P"], "certain": True}
STATISTIC = {"context_mi": {"by": "section", "feature": "word"}}


@dataclass
class Layout:
    size: int
    order: str
    page_labels: list
    items: list
    balanced: list
    report: dict


def order_pages(pages, name, size):
    if name == "manuscript":
        return sorted(pages, key=lambda page: page.order)
    if name == "section-blocked":
        return sorted(pages, key=lambda page: (page.section, page.order))
    shuffled = sorted(pages, key=lambda page: page.order)
    random.Random(PLAN["shuffle_order_seed"] + size).shuffle(shuffled)
    return shuffled


def describe_layout(pages, order):
    size = len(pages)
    labels = [page.section for page in pages]
    items = list(layout_lines(pages))
    real_by_section = Counter(section for _, section, _, is_opener in items if is_opener)
    section_slots = defaultdict(list)
    for index, (_, section, line, _) in enumerate(items):
        if line.unit == "P":
            section_slots[section].append(index)
    common_fraction = sum(real_by_section.values()) / sum(map(len, section_slots.values()))
    rng = random.Random(PLAN["routing_seed"] + size)
    balanced = [False] * len(items)
    balanced_by_section = {}
    for section, slots in sorted(section_slots.items()):
        count = round(common_fraction * len(slots))
        balanced_by_section[section] = count
        for index in rng.sample(slots, count):
            balanced[index] = True
    runs = []
    for label in labels:
        if runs and runs[-1][0] == label:
            runs[-1][1] += 1
        else:
            runs.append([label, 1])
    report = {
        "size": size,
        "order": order,
        "section_counts": dict(Counter(labels)),
        "page_ids": [page.id for page in pages],
        "section_runs": runs,
        "paragraph_lines": {section: len(slots) for section, slots in section_slots.items()},
        "observed_openers": dict(real_by_section),
        "balanced_openers": balanced_by_section,
        "common_opener_fraction": common_fraction,
    }
    return Layout(size, order, labels, items, balanced, report)


def prepare():
    training, _ = corpus.split_pages("practice", "zl")
    eligible = [page for page in training if dsl.select(dsl.tokens([page]), SELECT)]
    reserved = random.Random(PLAN["layout_seed"]).sample(eligible, max(PLAN["sizes"]))
    reserved_ids = {page.id for page in reserved}
    fitting = [page for page in training if page.id not in reserved_ids]
    layouts = [
        describe_layout(order_pages(reserved[:size], order, size), order)
        for size in PLAN["sizes"]
        for order in PLAN["orders"]
    ]
    expected = {
        31: {"B": 3, "H": 20, "P": 6, "S": 1, "T": 1},
        62: {"B": 4, "C": 2, "H": 40, "P": 6, "S": 8, "T": 2},
        124: {"A": 4, "B": 13, "C": 4, "H": 74, "P": 11, "S": 15, "T": 3},
    }
    assert len(fitting) == 68
    assert all(layout.report["section_counts"] == expected[layout.size] for layout in layouts)
    return layouts, learn(fitting), redteam._manuscript_4grams()


def line_streams(layouts, contexts, forbidden, seed):
    ordinary = Writer(contexts, seed, forbidden)
    opener = Writer(contexts, seed + 4096, forbidden)
    needed_ordinary = max(
        max(len(layout.items) - sum(item[3] for item in layout.items), len(layout.items) - sum(layout.balanced))
        for layout in layouts
    )
    needed_openers = max(
        max(sum(item[3] for item in layout.items), sum(layout.balanced)) for layout in layouts
    )
    ordinary_lines = [ordinary.line(False) for _ in range(needed_ordinary)]
    opener_lines = [opener.line(True) for _ in range(needed_openers)]
    common = {}
    for size in PLAN["sizes"]:
        layout = next(spec for spec in layouts if spec.size == size)
        probability = sum(item[3] for item in layout.items) / len(layout.items)
        mixture = random.Random(seed + PLAN["pooled_opener_seed_offset"])
        shared = Writer(contexts, seed, forbidden)
        common[size] = [
            shared.line(mixture.random() < probability) for _ in layout.items
        ]
    return ordinary_lines, opener_lines, common


def assign(layout, routing, streams):
    ordinary, openers, common = streams
    if routing == "one shared":
        lines = common[layout.size]
    else:
        normal = iter(ordinary)
        special = iter(openers)
        use_opener = [item[3] for item in layout.items] if routing == "two observed" else layout.balanced
        lines = [next(special) if is_opener else next(normal) for is_opener in use_opener]
    words = []
    page_ids = []
    selected = []
    for (page_index, _, line, _), written in zip(layout.items, lines, strict=True):
        words.extend(written)
        page_ids.extend([page_index] * len(written))
        selected.extend([line.unit == "P"] * len(written))
    return words, np.array(page_ids), np.array(selected, dtype=bool)


class MarginTest:
    def __init__(self, page_ids, selected, section_indices, seed):
        labels = np.asarray(section_indices)
        self.observed_pages = labels
        self.section_count = int(labels.max()) + 1
        self.page_ids = page_ids[selected]
        self.selected = np.flatnonzero(selected)
        self.observed = labels[self.page_ids]
        self.total = len(self.selected)
        self.log_count = np.zeros(self.total + 1)
        sizes = np.arange(1, self.total + 1)
        self.log_count[1:] = sizes * np.log2(sizes)
        self.fixed_section_mass = self.mass(np.bincount(self.observed))
        token_rng = np.random.default_rng(11091 + seed)
        page_rng = np.random.default_rng(22291 + seed)
        self.token_draws = [
            token_rng.permutation(len(selected))[selected] for _ in range(PLAN["permutations"])
        ]
        self.page_draws = [
            page_rng.permutation(labels)[self.page_ids] for _ in range(PLAN["permutations"])
        ]
        self.rotations = [np.roll(labels, offset)[self.page_ids] for offset in range(1, len(labels))]

    def mass(self, counts):
        return self.log_count[counts[counts > 1]].sum()

    def value(self, words, sections, word_mass, section_mass):
        joint = np.bincount(words * self.section_count + sections)
        return (self.mass(joint) - word_mass - section_mass + self.log_count[self.total]) / self.total

    def score(self, all_words):
        selected = all_words[self.selected]
        word_mass = self.mass(np.bincount(selected))
        observed = self.value(selected, self.observed, word_mass, self.fixed_section_mass)
        threshold = observed - PLAN["tie_tolerance_bits"]
        token_hits = 0
        for order in self.token_draws:
            shuffled = all_words[order]
            token_hits += self.value(
                shuffled, self.observed, self.mass(np.bincount(shuffled)), self.fixed_section_mass
            ) >= threshold
        def label_hits(assignments):
            return sum(
                self.value(selected, labels, word_mass, self.mass(np.bincount(labels))) >= threshold
                for labels in assignments
            )
        return [
            round(float(observed), 8), int(token_hits) + 1, int(label_hits(self.page_draws)) + 1,
            int(label_hits(self.rotations)) + 1,
        ]


def marker(length, forbidden, rng):
    while True:
        word = "z" + "".join(rng.choices(string.ascii_lowercase, k=length - 1))
        if word not in forbidden:
            return word


def intervention(words, page_ids, selected, section_indices, seed, size):
    word_set = set(words)
    index = {}
    assigned_markers = {}
    cases_by_section = defaultdict(list)
    for position in np.flatnonzero(selected):
        if len(words[position]) >= 4:
            section = section_indices[page_ids[position]]
            cases_by_section[section].append(position)
    rng = random.Random(26791 + 200 * seed + size)
    marker_rng = random.Random(295231)
    for section, positions in sorted(cases_by_section.items()):
        rng.shuffle(positions)
        for position in positions:
            length = len(words[position])
            key = (section, length)
            if key not in index:
                markers = []
                for _ in range(4):
                    spelling = marker(length, word_set, marker_rng)
                    word_set.add(spelling)
                    markers.append(spelling)
                index[key] = markers
            assigned_markers[position] = rng.choice(index[key])
    for dose in PLAN["doses_percent"]:
        affected = sorted(
            position for positions in cases_by_section.values()
            for position in positions[:round(dose * len(positions) / 100)]
        )
        planted = list(words)
        placebo = list(words)
        by_length = defaultdict(list)
        for position in affected:
            planted[position] = assigned_markers[position]
            by_length[len(words[position])].append(position)
        shuffle = random.Random(78821 + 200 * seed + size)
        for length in sorted(by_length):
            positions = by_length[length]
            spelling = [planted[position] for position in positions]
            shuffle.shuffle(spelling)
            for position, replacement in zip(positions, spelling, strict=True):
                placebo[position] = replacement
        yield dose, planted, placebo


def evaluate(seed, prepared):
    layouts, contexts, forbidden = prepared
    streams = line_streams(layouts, contexts, forbidden, seed)
    rows = []
    for layout in layouts:
        names = sorted(set(layout.page_labels))
        section_indices = [names.index(section) for section in layout.page_labels]
        for routing in PLAN["routing"]:
            words, page_ids, selected = assign(layout, routing, streams)
            tests = MarginTest(page_ids, selected, section_indices, seed)
            cases = [("base", 0, words)]
            for dose, planted, placebo in intervention(words, page_ids, selected, section_indices, seed, layout.size):
                cases.extend([("plant", dose, planted), ("placebo", dose, placebo)])
            random.Random(f"{seed}/{layout.size}/{layout.order}/{routing}/blind").shuffle(cases)
            for case, dose, sample in cases:
                vocabulary = {word: i for i, word in enumerate(dict.fromkeys(sample))}
                encoded = np.fromiter((vocabulary[word] for word in sample), dtype=np.int64, count=len(sample))
                scores = tests.score(encoded)
                if seed == 1 and case == "base":
                    selected_sections = tests.observed
                    records = [
                        {"w": sample[position], "section": names[section]}
                        for position, section in zip(tests.selected, selected_sections, strict=True)
                    ]
                    reference = dsl.statistic(STATISTIC, records, records)
                    assert math.isclose(scores[0], reference, rel_tol=0, abs_tol=5.1e-9), (scores[0], reference)
                rows.append([seed, layout.size, layout.order, routing, case, dose, *scores, tests.total])
    return sorted(rows)


_PREPARED = None


def run_seed(seed):
    return evaluate(seed, _PREPARED)


def main():
    global _PREPARED
    _PREPARED = prepare()
    layouts, _, _ = _PREPARED
    (WORK / "layouts.json").write_text(json.dumps([layout.report for layout in layouts], indent=2) + "\n")
    seeds = PLAN["background_seeds"] if len(sys.argv) == 1 else [int(value) for value in sys.argv[1:]]
    with ProcessPoolExecutor(max_workers=min(7, len(seeds))) as pool:
        for seed, rows in zip(seeds, pool.map(run_seed, seeds), strict=True):
            print(json.dumps(rows, separators=(",", ":")), flush=True)
            print(f"completed seed {seed} ({len(rows)} cases)", file=sys.stderr, flush=True)


if __name__ == "__main__":
    main()

