"""Summarize the frozen section calibration and package a single step proposal."""

from collections import defaultdict
import json
import math
from pathlib import Path
from statistics import median


WORK = Path(__file__).resolve().parent
PLAN = json.loads((WORK / "plan.json").read_text())
ORDER_ID = {name: index for index, name in enumerate(PLAN["orders"])}
ROUTING_ID = {name: index for index, name in enumerate(PLAN["routing"])}
CONDITION_ID = {"base": 0, "plant": 1, "placebo": 2}


def interval(hits, total):
    z = 1.959964
    estimate = hits / total
    denominator = 1 + z**2 / total
    center = (estimate + z**2 / (2 * total)) / denominator
    half = z * math.sqrt(estimate * (1 - estimate) / total + z**2 / (4 * total**2)) / denominator
    return [round(max(0, center - half), 4), round(min(1, center + half), 4)]


def read_rows():
    rows = [
        row
        for filename in ("pilot.jsonl", "remaining.jsonl")
        for line in (WORK / filename).read_text().splitlines()
        for row in json.loads(line)
    ]
    expected = len(PLAN["background_seeds"]) * len(PLAN["sizes"]) * len(PLAN["orders"]) * len(PLAN["routing"])
    assert len(rows) == expected * (1 + 2 * len(PLAN["doses_percent"]))
    assert len({tuple(row[:6]) for row in rows}) == len(rows)
    return sorted(rows)


def summarize(rows):
    groups = defaultdict(list)
    for row in rows:
        groups[tuple(row[1:6])].append(row[6:])
    counts = []
    for (size, order, routing, case, dose), group in sorted(groups.items()):
        assert len(group) == len(PLAN["background_seeds"])
        token_hits = sum(row[1] / 200 <= 0.05 for row in group)
        page_hits = sum(row[2] / 200 <= 0.05 for row in group)
        cyclic_hits = sum(row[3] / size <= 0.05 for row in group)
        rank = [row[3] for row in group]
        counts.append({
            "design": [size, order, routing, case, dose],
            "reject_at_0.05": [token_hits, page_hits, cyclic_hits],
            "wilson_95_intervals": [interval(hits, len(group)) for hits in (token_hits, page_hits, cyclic_hits)],
            "reject_at_0.01": [
                sum(row[1] / 200 <= 0.01 for row in group),
                sum(row[2] / 200 <= 0.01 for row in group),
                sum(row[3] / size <= 0.01 for row in group),
            ],
            "cyclic_rank_min_median_max": [min(rank), median(rank), max(rank)],
            "median_observed_bits": round(median(row[0] for row in group), 6),
        })
    return counts


def compact(row):
    seed, size, order, routing, case, dose, *measured = row
    return [seed, size, ORDER_ID[order], ROUTING_ID[routing], CONDITION_ID[case], dose, *measured]


def main():
    rows = read_rows()
    results = summarize(rows)
    (WORK / "summary.json").write_text(json.dumps(results, indent=2) + "\n")
    return rows, results


if __name__ == "__main__":
    main()
